// Copyright 2015-2021 Crytek GmbH / Crytek Group. All rights reserved.#include "StdAfx.h"#include "DepthOfField.h"#include "D3DPostProcess.h"#include <algorithm>float NGon_Rad(float theta, float n){	return cosf(PI / n) / cosf(theta - (2 * PI / n) * floorf((n * theta + PI) / (2 * PI)));}// The sharpening exponent raised over the iris polygon's radius function: 0 = perfect circle,// ~1 = the physical polygon, 2+ = deliberately sharpened corners, 4 = caricature. THE single// place this is decided - the gather kernel and the splat mask are two views of one iris and// must never derive it separately.//// Two things drive it. Stopping down reveals the polygon (round at f/1.2, complete by f/2.8,// deliberately overlapping the apertures that produce LARGE discs or the shape would never be// readable). And blade curvature: only a CURVED blade can retract into a circle. Straight// blades keep the fully formed polygon at EVERY aperture and cut visibly sharper corners, so// low curvature both floors the formation window and pushes the exponent toward caricature.// The knob has to read at a glance - tuned to the picture, not to arithmetic timidity.static float ComputeIrisShapeExponent(float fstop, float curvature){	const float minFstops = 1.2f;	const float maxFstops = 2.8f;	const float stopBlend = clamp_tpl((fstop - minFstops) / (maxFstops - minFstops), 0.0f, 1.0f);	const float straight = 1.0f - clamp_tpl(curvature, 0.0f, 1.0f);	// Straight blades are always fully formed; curved blades follow the f-stop window.	const float formed = straight + (1.0f - straight) * stopBlend;	const float strength = clamp_tpl(CRenderer::CV_r_DofBokehShapeStrength, 0.25f, 4.0f);	// Straight blades sharpen on top of forming: at curvature 0 the polygon runs at double	// strength (a caricature on purpose); at curvature 1 this reduces exactly to the legacy	// stopBlend * strength.	return formed * strength * (1.0f + straight);}// Shirley's concentric mappingVec4 CDepthOfFieldStage::ToUnitDisk(Vec4& origin, float blades, float shapeExponent, float rotation){	float phi;	float r;	const float a = 2 * origin.x - 1;	const float b = 2 * origin.y - 1;	if (abs(a) > abs(b)) // Use squares instead of absolute values	{		r = a;		phi = (PI / 4.0f) * (b / (a + 1e-6f));	}	else	{		r = b;		phi = (PI / 2.0f) - (PI / 4.0f) * (a / (b + 1e-6f));	}	// Shirley's mapping yields signed radii; fold the sign into the ANGLE before evaluating	// the polygon. The legacy code multiplied the sign back into the radius instead, which	// point-mirrors half the taps while keeping the un-mirrored polygon radius - harmless	// for the hardcoded (centro-symmetric) 8-gon it always ran with, but it averages any	// odd-sided polygon with its own mirror image and washes it back into a circle.	const float finalAngle = phi + (r < 0.0f ? PI : 0.0f);	// Rotating the radius function rotates the polygon; the tap directions themselves stay put,	// so the disc keeps its coverage and only the flat edges turn. Same phase the diffraction	// streaks use - one iris, one orientation.	const float rr = fabsf(r) * powf(NGon_Rad(finalAngle - rotation, blades), shapeExponent);	return Vec4(rr * cosf(finalAngle), rr * sinf(finalAngle), 0.0f, 0.0f);}// Mask-domain gather kernel. When the mask is the smaller aperture, the gather taps are// importance-sampled from the mask texture itself, so the gather's energy distribution - the// soft halo under each sharp splat - takes the mask's silhouette instead of staying a disc.// The texture is re-read from disk through CryPak (the GPU resource keeps no CPU copy); only// uncompressed 32-bit single-surface power-of-two DDS masks qualify - all six engine-shipped// bokeh masks do - and anything else keeps the polygon kernel and says so once. Taps cluster// in the mask's open regions, which IS the physical energy concentration of a low// transmittance mask; no extra normalization wanted.bool CDepthOfFieldStage::EnsureMaskKernelCDF(const char* szTexName, float fIrisRadius){	// Quantized so a smooth aperture pull rebuilds the pupil in steps rather than every frame	// (a 64x64 rebuild is cheap, not free). >= 1.5 reaches past the mask's corners: no clipping.	const float fIrisQ = min(floorf(clamp_tpl(fIrisRadius, 0.2f, 1.5f) * 20.0f + 0.5f) / 20.0f, 1.5f);	if (m_maskCDFTexName == szTexName)	{		if (!m_maskPixelsValid)			return false;                       // unusable texture, already reported once		if (m_maskCDFValid && fabsf(fIrisQ - m_maskCDFIrisRadius) < 1e-4f)			return true;		return BuildMaskPupilCDF(fIrisQ);	}	m_maskCDFTexName = szTexName;	m_maskCDFValid = false;	m_maskPixelsValid = false;	m_maskCDFIrisRadius = -1.0f;	const char* szFail = nullptr;	std::vector<uint8> data;	{		FILE* pFile = gEnv->pCryPak->FOpen(szTexName, "rb");		if (!pFile)			szFail = "file not found";		else		{			gEnv->pCryPak->FSeek(pFile, 0, SEEK_END);			const size_t nSize = (size_t)gEnv->pCryPak->FTell(pFile);			gEnv->pCryPak->FSeek(pFile, 0, SEEK_SET);			data.resize(nSize);			if (nSize < 128 + 16 || gEnv->pCryPak->FReadRaw(data.data(), 1, nSize, pFile) != nSize)				szFail = "read failed";			gEnv->pCryPak->FClose(pFile);		}	}	int w = 0, h = 0;	if (!szFail)	{		if (memcmp(data.data(), "DDS ", 4) != 0)			szFail = "not a DDS";		else		{			const uint32* pHdr = (const uint32*)(data.data() + 4);			h = (int)pHdr[2];			w = (int)pHdr[3];			const uint32 nPFFlags = pHdr[19];  // pixel format flags			const uint32 nFourCC = pHdr[20];			const uint32 nRGBBits = pHdr[21];			if ((nPFFlags & 0x40) == 0 || nFourCC != 0 || nRGBBits != 32)				szFail = "not uncompressed 32-bit";			else if (w < 4 || h < 4 || w > 512 || h > 512 || (w & (w - 1)) != 0 || (h & (h - 1)) != 0)				szFail = "unsupported dimensions";			else if (data.size() < 128 + (size_t)w * h * 4)				szFail = "truncated pixel data";		}	}	if (szFail)	{		CryLog("[DOF] gather kernel: '%s' not usable for importance sampling (%s), keeping the polygon kernel", szTexName, szFail);		return false;	}	// Keep the R channel (file byte order is B,G,R,A): the pupil is rebuilt from it every time	// the iris radius steps, without touching the file again.	const uint8* pPix = data.data() + 128;	m_maskCDFWidth = w;	m_maskCDFHeight = h;	m_maskPixels.resize((size_t)w * h);	float fSum = 0.0f;	for (size_t i = 0; i < (size_t)w * h; i++)	{		m_maskPixels[i] = pPix[i * 4 + 2];		fSum += (float)m_maskPixels[i];	}	m_maskPixelsValid = true;	CryLog("[DOF] gather kernel: importance-sampled from '%s' (%dx%d, mean=%.2f)",	       szTexName, w, h, fSum / ((float)w * (float)h * 255.0f));	return BuildMaskPupilCDF(fIrisQ);}// Pupil = mask x iris disc of radius fIrisRadius (mask units, 1 = the mask's bounding circle).// Marginal CDF over rows + conditional per row; a half-count floor keeps fully blocked regions// measurable so both CDFs stay invertible. Also resolves the pupil's fill fraction of the splat// quad (which spans the pupil's bounding square), so the energy gain can divide by it and a thin// cut-out deposits as much light as the disc it replaces - exactly, per iris step, instead of// the old measured-average constant.bool CDepthOfFieldStage::BuildMaskPupilCDF(float fIrisRadius){	const int w = m_maskCDFWidth;	const int h = m_maskCDFHeight;	const float fBound = min(fIrisRadius, 1.0f);	const float fIrisSq = fIrisRadius * fIrisRadius;	m_maskRowCDF.resize(h);	m_maskColCDF.resize((size_t)h * w);	float fTotal = 0.0f;	float fFillSum = 0.0f;	int nFillCount = 0;	for (int y = 0; y < h; y++)	{		const float fy = ((float)y + 0.5f) / (float)h * 2.0f - 1.0f;		float fRow = 0.0f;		for (int x = 0; x < w; x++)		{			const float fx = ((float)x + 0.5f) / (float)w * 2.0f - 1.0f;			const bool bInIris = (fx * fx + fy * fy) <= fIrisSq;			const float fPupil = bInIris ? (float)m_maskPixels[(size_t)y * w + x] : 0.0f;			fRow += fPupil + 0.5f;			m_maskColCDF[(size_t)y * w + x] = fRow;			if (fabsf(fx) <= fBound && fabsf(fy) <= fBound)			{				fFillSum += fPupil / 255.0f;				nFillCount++;			}		}		const float fInvRow = 1.0f / fRow;		for (int x = 0; x < w; x++)			m_maskColCDF[(size_t)y * w + x] *= fInvRow;		fTotal += fRow;		m_maskRowCDF[y] = fTotal;	}	const float fInvTotal = 1.0f / fTotal;	for (int y = 0; y < h; y++)		m_maskRowCDF[y] *= fInvTotal;	m_maskBound = fBound;	m_maskFill = nFillCount > 0 ? max(fFillSum / (float)nFillCount, 0.02f) : 1.0f;	m_maskCDFIrisRadius = fIrisRadius;	m_maskCDFValid = true;	return true;}// Van der Corput radical inverse in base 2; paired with (i + 0.5) / N it forms the// Hammersley set. The mask kernel needs a low-discrepancy pattern instead of the// stratified grid: a regular grid collapses under CDF inversion - only nSide distinct// v values means only nSide distinct mask ROWS ever get sampled, which turns thin// vertical structure in the mask (a note stem) into discrete horizontal bands at// large CoC. Deterministic across frames, so no temporal noise.static float RadicalInverse2(uint32 i){	i = (i << 16) | (i >> 16);	i = ((i & 0x00ff00ffu) << 8) | ((i & 0xff00ff00u) >> 8);	i = ((i & 0x0f0f0f0fu) << 4) | ((i & 0xf0f0f0f0u) >> 4);	i = ((i & 0x33333333u) << 2) | ((i & 0xccccccccu) >> 2);	i = ((i & 0x55555555u) << 1) | ((i & 0xaaaaaaaau) >> 1);	return (float)i * 2.3283064365386963e-10f; // * 2^-32}Vec4 CDepthOfFieldStage::SampleMaskKernelTap(float u, float v) const{	// Standard 2D CDF inversion: the marginal row CDF with v, that row's conditional column	// CDF with u, linear interpolation inside the winning bin.	const int w = m_maskCDFWidth;	const int h = m_maskCDFHeight;	int y = (int)(std::lower_bound(m_maskRowCDF.begin(), m_maskRowCDF.end(), v) - m_maskRowCDF.begin());	y = min(y, h - 1);	const float fPrevRow = (y > 0) ? m_maskRowCDF[y - 1] : 0.0f;	const float fRowSpan = max(m_maskRowCDF[y] - fPrevRow, 1e-9f);	const float fy = ((float)y + clamp_tpl((v - fPrevRow) / fRowSpan, 0.0f, 1.0f)) / (float)h;	const float* pCol = &m_maskColCDF[(size_t)y * w];	int x = (int)(std::lower_bound(pCol, pCol + w, u) - pCol);	x = min(x, w - 1);	const float fPrevCol = (x > 0) ? pCol[x - 1] : 0.0f;	const float fColSpan = max(pCol[x] - fPrevCol, 1e-9f);	const float fx = ((float)x + clamp_tpl((u - fPrevCol) / fColSpan, 0.0f, 1.0f)) / (float)w;	// Same disc-space convention as the splat quad: quad-local uv to offsets. No vertical	// flip - the gather shader's tap offsets are applied in texture space (v down), the	// same space the mask is authored in, so the halo lines up with the splatted	// silhouette as-is. (A negation here was verified upside-down in the engine.)	// Taps are relative to the CoC radius, which is the pupil's BOUNDING radius: once the iris	// is the smaller hole the mask coordinates are rescaled by it, same as the splat quad.	const float fInvBound = 1.0f / max(m_maskBound, 1e-3f);	const float px = (fx * 2.0f - 1.0f) * fInvBound;	const float py = (fy * 2.0f - 1.0f) * fInvBound;	// Mask rotation: the mask is its own element, turned independently of the iris phase. The	// splat samples the texture through the inverse rotation, so both views turn together.	const float c = cosf(m_maskRotation);	const float s = sinf(m_maskRotation);	return Vec4(px * c - py * s, px * s + py * c, 0.0f, 0.0f);}void CDepthOfFieldStage::Execute(){	FUNCTION_PROFILER_RENDERER();	m_bWroteHDRTarget = false;	CDepthOfField* pDofRenderTech = (CDepthOfField*)PostEffectMgr()->GetEffect(EPostEffectID::DepthOfField);	SDepthOfFieldParams dofParams = pDofRenderTech->GetParams();	if (dofParams.vFocus.w < 0.0001f)		return;	PROFILE_LABEL_SCOPE("DOF");	CShader* pShader = CShaderMan::s_shPostDepthOfField; // s_shPostMotionBlur;	Vec4 vFocus = dofParams.vFocus;	vFocus.w *= 2;  // For backwards compatibility	float fFNumber = dofParams.fApertureFNumber;	float fNumApertureSides = clamp_tpl(dofParams.fApertureBlades, 3.0f, 16.0f);	// r_DepthOfFieldBokehQuality N (N >= 3): diagnostic force mode - N blades at full	// polygon blend, independent of whatever game code feeds the params. A triangle (3)	// is unmissable if the kernel shaping works at all.	if (CRenderer::CV_r_DofBokehQuality >= 3)	{		fNumApertureSides = (float)CRenderer::CV_r_DofBokehQuality;		fFNumber = 8.0f;	}	// Ground truth log: what actually reaches the kernel, once per change.	static float s_lastLoggedBlades = -1.0f;	static float s_lastLoggedFNumber = -1.0f;	if (fabsf(fNumApertureSides - s_lastLoggedBlades) > 0.01f || fabsf(fFNumber - s_lastLoggedFNumber) > 0.01f)	{		s_lastLoggedBlades = fNumApertureSides;		s_lastLoggedFNumber = fFNumber;		CryLog("[DOF] kernel blades=%.0f fNumber=%.1f%s", fNumApertureSides, fFNumber,		       CRenderer::CV_r_DofBokehQuality >= 3 ? " (FORCED)" : "");	}	if (dofParams.bGameMode)	{		dofParams.vFocus.x = 1.0f / (vFocus.z + 1e-6f);		dofParams.vFocus.y = -vFocus.y / (vFocus.z + 1e-6f);		dofParams.vFocus.z = -1.0f / (vFocus.w + 1e-6f);		dofParams.vFocus.w = vFocus.x / (vFocus.w + 1e-6f);	}	else	{		dofParams.vFocus.x = 1.0f / (vFocus.y + 1e-6f);		dofParams.vFocus.y = -vFocus.z / (vFocus.y + 1e-6f);		dofParams.vFocus.z = 1.0f / (vFocus.x + 1e-6f);		dofParams.vFocus.w = -vFocus.z / (vFocus.x + 1e-6f);	}	// Iris phase, shared with the diffraction streaks so a rotating aperture turns the bokeh	// polygon and the sunstars together.	const float fBladeRotation = dofParams.fBladeRotation;	// Resolved once, consumed by the gather taps below and by the splat mask in the hybrid	// overlay. The diagnostic force mode pins fFNumber to 8 and the curvature to fully curved,	// which reduces the exponent to the legacy strength-at-full-formation.	const float fBladeCurvatureEff = (CRenderer::CV_r_DofBokehQuality >= 3) ? 1.0f : dofParams.fBladeCurvature;	const float fIrisExponent = ComputeIrisShapeExponent(fFNumber, fBladeCurvatureEff);	// Anamorphic squeeze. The cylindrical element compresses the pupil image horizontally, so	// the gather kernel's horizontal reach shrinks by the same factor while the vertical reach	// stays the spherical CoC: every out-of-focus disc becomes a vertical oval of	// height : width = S : 1, which is the desqueezed anamorphic look. 1 = identity.	const float fSqueeze = clamp_tpl(dofParams.fAnamorphicSqueeze, 1.0f, 2.0f);	// Mask-domain gather: when the mask is the smaller aperture, the taps come from the mask	// texture's CDF so even the soft halo takes the silhouette. The diagnostic force mode	// keeps the polygon kernel - diagnostics outrank the mask. The splat pass makes its own	// (unforced) domain call; the two agree everywhere outside the diagnostic.	// Pupil = mask x iris. fIrisRadius = N_mask / N is the iris radius in mask units: above 1	// the mask bounds the pupil and the polygon only trims what pokes past it, below 1 the iris	// stops down THROUGH the mask, clipping it corner by corner. Once the iris sits deep inside	// the mask's open centre the mask cannot shape anything, so the polygon kernel takes over.	const bool  bShapeTexForGather = CRenderer::CV_r_DofBokehQuality < 3 && CTexture::IsTextureExist(dofParams.pBokehShapeTex);	const float fIrisRadius = max(dofParams.fMaskFNumber, 0.7f) / max(dofParams.fApertureFNumber, 0.7f);	const bool  bGatherMaskDomain = bShapeTexForGather && fIrisRadius > 0.35f;	const bool  bMaskKernel = bGatherMaskDomain && EnsureMaskKernelCDF(dofParams.pBokehShapeTex->GetName(), fIrisRadius);	m_maskRotation = dofParams.fMaskRotation;	// Domain transitions were previously silent, which made mask-kernel dropouts (CDF	// fallback, texture unbinds, f-number crossing) look like timing bugs. One line per	// change, never per frame.	static bool s_bLastMaskKernel = false;	static bool s_bLastMaskDomain = false;	if (bMaskKernel != s_bLastMaskKernel || bGatherMaskDomain != s_bLastMaskDomain)	{		s_bLastMaskKernel = bMaskKernel;		s_bLastMaskDomain = bGatherMaskDomain;		CryLog("[DOF] gather domain=%s (N=%.2f maskN=%.2f texValid=%d cdfOk=%d)",		       bMaskKernel ? "MASK" : "iris",		       dofParams.fApertureFNumber, dofParams.fMaskFNumber,		       CTexture::IsTextureExist(dofParams.pBokehShapeTex) ? 1 : 0,		       bMaskKernel ? 1 : 0);	}	Vec4 vDofParams0 = dofParams.vFocus;	const float fNearestDofScaleBoost = dofParams.bGameMode ? CRenderer::CV_r_dofMinZBlendMult : 1.0f;	Vec4 vDofParams1 = Vec4(CRenderer::CV_r_dofMinZ + dofParams.vMinZParams.x, CRenderer::CV_r_dofMinZScale + dofParams.vMinZParams.y, fNearestDofScaleBoost, vFocus.w);	// For better blending later	m_passCopySceneTarget.Execute(m_graphicsPipelineResources.m_pTexHDRTarget, m_graphicsPipelineResources.m_pTexSceneTarget);	static CCryNameR dofFocusParam0Name("vDofParamsFocus0");	static CCryNameR dofFocusParam1Name("vDofParamsFocus1");	static CCryNameR dofTapsName("g_Taps");	// TODO: Compute shader! because the targets are not compressed / able anyway, and we can half resource allocation)	{		// 1st downscale stage		{			PROFILE_LABEL_SCOPE("DOWNSCALE LAYERS");			if (m_passLayerDownscale.IsDirty())			{				static CCryNameTSCRC techNameDownscale("DownscaleDof");				m_passLayerDownscale.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);				m_passLayerDownscale.SetTechnique(pShader, techNameDownscale, 0);				m_passLayerDownscale.SetRenderTarget(0, m_graphicsPipelineResources.m_pTexHDRTargetMaskedScaled[0][0]);  // Near				m_passLayerDownscale.SetRenderTarget(1, m_graphicsPipelineResources.m_pTexHDRTargetMaskedScaled[0][1]);  // Far				m_passLayerDownscale.SetRenderTarget(2, m_graphicsPipelineResources.m_pTexSceneCoC[0]);      // CoC Near/Far				m_passLayerDownscale.SetState(GS_NODEPTHTEST);				m_passLayerDownscale.SetTextureSamplerPair(0, m_graphicsPipelineResources.m_pTexLinearDepth, EDefaultSamplerStates::PointClamp);				m_passLayerDownscale.SetTextureSamplerPair(1, m_graphicsPipelineResources.m_pTexHDRTarget, EDefaultSamplerStates::LinearClamp);				m_passLayerDownscale.SetRequirePerViewConstantBuffer(true);			}			m_passLayerDownscale.BeginConstantUpdate();			m_passLayerDownscale.SetConstant(dofFocusParam0Name, vDofParams0, eHWSC_Pixel);			m_passLayerDownscale.SetConstant(dofFocusParam1Name, vDofParams1, eHWSC_Pixel);			m_passLayerDownscale.Execute();		}		// 2nd downscale stage (tile min CoC)		{			PROFILE_LABEL_SCOPE("MIN COC DOWNSCALE");			for (uint32 i = 1; i < MIN_DOF_COC_K; i++)			{				if (m_passTileMinCoC[i].IsDirty())				{					static CCryNameTSCRC techNameTileMinCoC("TileMinCoC");					m_passTileMinCoC[i].SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_VS);					m_passTileMinCoC[i].SetTechnique(pShader, techNameTileMinCoC, 0);					m_passTileMinCoC[i].SetRenderTarget(0, m_graphicsPipelineResources.m_pTexSceneCoC[i]);  // Near					m_passTileMinCoC[i].SetState(GS_NODEPTHTEST);					m_passTileMinCoC[i].SetTextureSamplerPair(0, m_graphicsPipelineResources.m_pTexSceneCoC[i - 1], EDefaultSamplerStates::LinearClamp);				}				m_passTileMinCoC[i].BeginConstantUpdate();				const Vec4 vParams = Vec4((float)m_graphicsPipelineResources.m_pTexSceneCoC[i - 1]->GetWidth(), (float)m_graphicsPipelineResources.m_pTexSceneCoC[i - 1]->GetHeight(),				                          1.0f / (float)m_graphicsPipelineResources.m_pTexSceneCoC[i - 1]->GetWidth(), 1.0f / (float)m_graphicsPipelineResources.m_pTexSceneCoC[i - 1]->GetHeight());				m_passTileMinCoC[i].SetConstant(dofFocusParam1Name, vParams, eHWSC_Vertex);				m_passTileMinCoC[i].Execute();			}		}	}	{		// 1st gather pass		{			const int32 nSquareTapsSide = 7;			const float fRecipTaps = 1.0f / ((float)nSquareTapsSide - 1.0f);			Vec4 vTaps[nSquareTapsSide * nSquareTapsSide];			for (int32 y = 0; y < nSquareTapsSide; ++y)			{				for (int32 x = 0; x < nSquareTapsSide; ++x)				{					Vec4 t = Vec4(x * fRecipTaps, y * fRecipTaps, 0, 0);					vTaps[x + y * nSquareTapsSide] = bMaskKernel ? SampleMaskKernelTap(((float)(x + y * nSquareTapsSide) + 0.5f) / (float)(nSquareTapsSide * nSquareTapsSide), RadicalInverse2((uint32)(x + y * nSquareTapsSide)))					                                             : ToUnitDisk(t, fNumApertureSides, fIrisExponent, fBladeRotation);				}			}			// Applied to the finished tap, so both the polygon and the mask kernel take the oval.			if (fSqueeze > 1.001f)			{				for (int32 i = 0; i < nSquareTapsSide * nSquareTapsSide; ++i)					vTaps[i].x /= fSqueeze;			}			PROFILE_LABEL_SCOPE("FAR/NEAR LAYER");			if (m_passGather0.IsDirty())			{				static CCryNameTSCRC techDOF("Dof");				m_passGather0.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);				m_passGather0.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);				m_passGather0.SetTechnique(pShader, techDOF, 0);				m_passGather0.SetRenderTarget(0, m_graphicsPipelineResources.m_pTexHDRTargetMaskedScaled[0][2]);				m_passGather0.SetRenderTarget(1, m_graphicsPipelineResources.m_pTexHDRTargetMaskedScaled[0][3]);				m_passGather0.SetRenderTarget(2, m_graphicsPipelineResources.m_pTexSceneCoCTemp);				m_passGather0.SetState(GS_NODEPTHTEST);				m_passGather0.SetTexture(0, m_graphicsPipelineResources.m_pTexLinearDepthScaled[0]);				m_passGather0.SetTexture(4, m_graphicsPipelineResources.m_pTexSceneCoC[MIN_DOF_COC_K - 1]);				m_passGather0.SetSampler(0, EDefaultSamplerStates::PointClamp);				m_passGather0.SetTexture(1, m_graphicsPipelineResources.m_pTexHDRTargetMaskedScaled[0][0]);				m_passGather0.SetTexture(2, m_graphicsPipelineResources.m_pTexHDRTargetMaskedScaled[0][1]);				m_passGather0.SetSampler(1, EDefaultSamplerStates::LinearClamp);			}			m_passGather0.BeginConstantUpdate();			vDofParams1.z = nSquareTapsSide * nSquareTapsSide;			m_passGather0.SetConstant(dofFocusParam0Name, vDofParams0, eHWSC_Pixel);			m_passGather0.SetConstant(dofFocusParam1Name, vDofParams1, eHWSC_Pixel);			m_passGather0.SetConstantArray(dofTapsName, vTaps, nSquareTapsSide * nSquareTapsSide, eHWSC_Pixel);			m_passGather0.Execute();		}		// 2nd gather iteration		{			const int32 nSquareTapsSide = 3;			const float fRecipTaps = 1.0f / ((float)nSquareTapsSide - 1.0f);			Vec4 vTaps[nSquareTapsSide * nSquareTapsSide];			for (int32 y = 0; y < nSquareTapsSide; ++y)			{				for (int32 x = 0; x < nSquareTapsSide; ++x)				{					Vec4 t = Vec4(x * fRecipTaps, y * fRecipTaps, 0, 0);					vTaps[x + y * nSquareTapsSide] = bMaskKernel ? SampleMaskKernelTap(((float